// Generado a partir del deck "MASIVO 1.0 – 18/08/2026" (Nutresa).
// Los PSP provienen del mismo deck; ver productos_revision.csv. Los combos promocionales
// (referencias "CMU") quedaron fuera a propósito: son mecánicas internas con vigencia.
//
// PENDIENTE DE CONFIRMAR CON EL ASESOR COMERCIAL — Gomas Bénet.
// Las páginas 124 y 125 del deck le ponen PSP $36.500 a las Gomas de Vinagre de
// Manzana (2037217) y Citrato de Magnesio (2037218), que es el precio que quedó
// aquí. Las páginas 68 a 71 traen esos mismos empaques dentro de un combo, bajo
// otros códigos (1080144, 1080145, 1072792, 1071985) y con PSP $48.900. Se
// dejó el de la página de producto por ser la más específica, y los códigos de
// combo NO se agregaron para no duplicar la referencia en el catálogo. Las
// Gomas de Colágeno (2019271) y de Zinc + Vitamina C (2019270) siguen sin
// precio: su página no publica ningún PSP.
// codigoParcial = true → el deck mostraba solo los últimos dígitos del código SAP; completar.

export type UnidadPedido = "unidad";

export interface Producto {
  id: string;
  marca: string;
  categoria: string;
  /**
   * Segundo nivel de la categoría ("Pastas" › "Rellenas"). Es opcional porque
   * no todas las categorías lo necesitan: hoy solo "Untables" va sin él, y sus
   * productos se filtran únicamente por el primer nivel.
   *
   * Los valores válidos de cada categoría están en SUBCATEGORIAS, más abajo;
   * ese mapa es también el que ordena los botones del panel de filtros.
   */
  subcategoria?: string;
  nombre: string;
  presentacion: string;
  /** Código SAP (puede venir vacío o parcial; ver codigoParcial) */
  codigo: string;
  codigoParcial: boolean;
  /**
   * PSP (precio sugerido al público) en pesos colombianos, tomado del deck
   * "MASIVO 1.0 – 18/08/2026" y verificado contra la imagen de su página.
   *
   * Solo lo tienen las referencias cuya página declara un PSP explícito. Las
   * demás quedan sin el campo y la tarjeta no muestra precio: el deck trae
   * para ellas precios de lista, que son información interna y no se guardan
   * en el repositorio (ver productos_revision.csv para el detalle por
   * referencia).
   */
  precio?: number;
  /** Cómo lo despacha el proveedor (plegadiza x 12, caja x 24…). Informativo. */
  embalaje: string;
  /** Página del deck de origen, para verificación interna */
  paginaPdf: number;
  /**
   * Foto real del producto. Admite dos formas:
   *
   *  - NOMBRE DE ARCHIVO ('1078187.png'): foto oficial del fabricante en
   *    src/assets/productos/, nombrada con el código SAP. Es el caso normal.
   *    Al ir por src/assets pasa por el optimizador de Astro, que sirve un
   *    WebP pequeño en vez del original de 1000 px.
   *  - RUTA ABSOLUTA ('/img/innovacion/jumbo-pistacho-dubai.jpg'): archivo
   *    suelto en public/. Lo usan las referencias de innovación, cuyas fotos
   *    se montaron a mano antes de existir el catálogo descargado.
   *
   * CÓMO SE LLENA: se asigna solo cuando la foto está confirmada contra el
   * CÓDIGO SAP de la referencia, no por parecido de nombre. Dos referencias
   * de la misma marca pueden llamarse casi igual y cambiar solo en la
   * presentación (Bénet Kids vs. Bénet, plegadiza x 4 vs. x 8), así que el
   * código es lo único que amarra la foto al producto correcto. Las fotos
   * descargadas de tiendanutresaencasa.com se cruzaron por el RefId de VTEX,
   * que es justamente ese código SAP.
   *
   * QUÉ PASA SI SE DEJA VACÍO: la tarjeta del armador de pedidos muestra el
   * logotipo de la marca, como hasta ahora. No hay que tocar ningún
   * componente para prender la foto: basta con dejar el archivo en
   * src/assets/productos/ y nombrarlo aquí (ver CatalogoPedido.astro).
   */
  imagen?: string;
}

