export const productosPorMarca = (marca: string) => productos.filter((p) => p.marca === marca);
export const buscarProductos = (q: string) => {
  const n = q.trim().toLowerCase();
  if (!n) return productos;
  return productos.filter((p) => `${p.marca} ${p.nombre} ${p.presentacion} ${p.codigo}`.toLowerCase().includes(n));
};
